import 'package:dio/dio.dart';
import '../core/api_exceptions.dart';import '../models/book.dart';import '../models/book_query.dart';import '../models/page_result.dart';import 'book_repository.dart';
class ApiBookRepository implements BookRepository{final Dio dio;CancelToken? _findToken;ApiBookRepository(this.dio);Map<String,dynamic> _write(Book b)=>{'title':b.title,'isbn':b.isbn,'year':b.year,'pages':b.pages,'publisherId':b.publisherId,'authorIds':b.authorIds,'genreIds':b.genreIds,'copiesTotal':b.copiesTotal,'copiesAvailable':b.copiesAvailable};
@override Future<PageResult<Book>> find(BookQuery q)async{_findToken?.cancel('Устаревший поиск');final token=CancelToken();_findToken=token;return retryRead(()=>guard(()async{final r=await dio.get('/books',cancelToken:token,queryParameters:{if(q.search.trim().isNotEmpty)'search':q.search.trim(),if(q.genreId!=null)'genreId':q.genreId,if(q.publisherId!=null)'publisherId':q.publisherId,if(q.yearFrom!=null)'yearFrom':q.yearFrom,if(q.yearTo!=null)'yearTo':q.yearTo,'sort':'${q.sortField},${q.sortAscending?'asc':'desc'}','page':q.page,'size':q.size,if(q.includeDeleted)'includeDeleted':true,if(q.serverFail!=null)'__fail':q.serverFail,if(q.serverDelay!=null)'__delay':q.serverDelay});final d=Map<String,dynamic>.from(r.data as Map);return PageResult(items:(d['items'] as List? ?? []).whereType<Map>().map((e)=>Book.fromJson(Map<String,dynamic>.from(e))).toList(),page:d['page'] as int? ?? 1,size:d['size'] as int? ?? q.size,total:d['total'] as int? ?? 0);}));}
@override Future<Book?> findById(int id)=>retryRead(()=>guard(()async{final r=await dio.get('/books/$id');return Book.fromJson(Map<String,dynamic>.from(r.data as Map));}));
@override Future<Book> create(Book b)=>guard(()async{final r=await dio.post('/books',data:_write(b));return Book.fromJson(Map<String,dynamic>.from(r.data as Map));});
@override Future<Book> update(Book b)=>guard(()async{final r=await dio.put('/books/${b.id}',data:_write(b));return Book.fromJson(Map<String,dynamic>.from(r.data as Map));});
@override Future<void> softDelete(int id)=>guard(()async{await dio.delete('/books/$id');});@override Future<void> hardDelete(int id)=>guard(()async{await dio.delete('/books/$id',queryParameters:{'hard':true});});@override Future<void> restore(int id)=>guard(()async{await dio.post('/books/$id/restore');});@override Future<int> deleteMany(List<int> ids)=>guard(()async{final r=await dio.post('/books/bulk-delete',data:{'ids':ids});return (r.data as Map)['deleted'] as int? ?? 0;});@override Future<int> countByPublisher(int id)=>retryRead(()=>guard(()async{final r=await dio.get('/books',queryParameters:{'publisherId':id,'page':1,'size':1});return (r.data as Map)['total'] as int? ?? 0;}));Future<void> issue(int id)=>guard(()async{await dio.post('/books/$id/issue');});}
